// Use Code node to make HTTP request to Supabase
const https = require('https');

const SUPABASE_URL = 'kozhlejudselgtmohdfm.supabase.co';
const SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImtvemhsZWp1ZHNlbGd0bW9oZGZtIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc1NzQwNDI5OCwiZXhwIjoyMDcyOTgwMjk4fQ.LWosNpPJO_clOXXYa5pqGM36S-FLANk71F8BvcsJf2g';

return new Promise((resolve, reject) => {
  const options = {
    hostname: SUPABASE_URL,
    path: '/rest/v1/tenants?select=*,units(*,properties(*)),tenant_info(*)&status=eq.active',
    method: 'GET',
    headers: {
      'Authorization': `Bearer ${SUPABASE_KEY}`,
      'apikey': SUPABASE_KEY,
      'Content-Type': 'application/json'
    }
  };

  const req = https.request(options, (res) => {
    let data = '';

    res.on('data', (chunk) => {
      data += chunk;
    });

    res.on('end', () => {
      try {
        const tenants = JSON.parse(data);

        if (res.statusCode === 200) {
          console.log(`Successfully retrieved ${tenants.length} tenants`);

          // Process each tenant
          const processedTenants = tenants.map(tenant => {
            return {
              json: {
                id: tenant.id,
                status: tenant.status,
                rent_amount: tenant.rent_amount,
                lease_start_date: tenant.lease_start_date,
                tenant_name: tenant.tenant_info?.full_name || 'N/A',
                phone: tenant.tenant_info?.phone || 'N/A',
                email: tenant.tenant_info?.email || 'N/A',
                property_address: tenant.units?.properties?.address || 'N/A',
                unit_number: tenant.units?.unit_number || 'N/A',
                property_name: tenant.units?.properties?.name || 'N/A'
              }
            };
          });

          resolve(processedTenants);
        } else {
          console.error(`HTTP Error: ${res.statusCode}`);
          console.error('Response:', data);
          reject(new Error(`HTTP ${res.statusCode}: ${data}`));
        }
      } catch (error) {
        console.error('Parse Error:', error.message);
        console.error('Raw data:', data);
        reject(error);
      }
    });
  });

  req.on('error', (error) => {
    console.error('Request Error:', error.message);
    reject(error);
  });

  req.end();
});
